import { Project } from '../../src'
import { Diagnostic } from '@servicenow/sdk-build-core'

describe('Unsupported syntax tests', () => {
    test('Unsupported syntax should produce diagnostic errors', async () => {
        const project = new Project()
        const file = project.addFile({
            path: 'test.now.ts',
            content: `import { Role } from '@servicenow/sdk/core'

let value = 'red'
if (true) {
    value = 'blue'
} else {
    value = 'green'
}


Role({
    name: 'test',
    description: value,
})`,
        })

        const diagnostics = await file.getDiagnostics()
        const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error).map((d) => d.message)

        expect(errors).toHaveLength(3)
        expect(errors[0]).toBe('Declaration kind "let" is not supported. Only const variables are supported.')
        expect(errors[1]).toBe('Node kind "IfStatement" is not allowed in Fluent files.')
        expect(errors[2]).toBe('Unsupported statement in Fluent source file.')
    })

    test('Unsupported syntax can be ignored (top level)', async () => {
        const project = new Project()
        const file = project.addFile({
            path: 'test.now.ts',
            content: `import { Role } from '@servicenow/sdk/core'

let value = 'red'

// @fluent-ignore
if (true) {
    value = true ? 'blue' : 'yellow'
} else {
    value = 'green'
}


Role({
    name: 'test',
    description: value,
})`,
        })

        const diagnostics = await file.getDiagnostics()
        const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error).map((d) => d.message)

        expect(errors).toHaveLength(2)
        expect(errors[0]).toBe('Declaration kind "let" is not supported. Only const variables are supported.')
        expect(errors[1]).toBe('Unsupported statement in Fluent source file.')
    })

    test('Unsupported syntax can be ignored (child level)', async () => {
        const project = new Project()
        const file = project.addFile({
            path: 'test.now.ts',
            content: `import { Role } from '@servicenow/sdk/core'

let value = 'red'
if (true) {
    // @fluent-ignore
    value = true ? 'blue' : 'yellow'
} else {
    value = 'green'
}


Role({
    name: 'test',
    description: value,
})`,
        })

        const diagnostics = await file.getDiagnostics()
        const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error).map((d) => d.message)

        expect(errors).toHaveLength(3)
        expect(errors[0]).toBe('Declaration kind "let" is not supported. Only const variables are supported.')
        expect(errors[1]).toBe('Node kind "IfStatement" is not allowed in Fluent files.')
        expect(errors[2]).toBe('Unsupported statement in Fluent source file.')
    })
})
